text:
{
  "design": {
    "theme": "chalk",
    "picture_style": "photo"
  },
  "flow": [
    {
      "slide": 1,
      "does": "Recall heartbeat and breathing during movement",
      "look_at": {
        "kind": "picture",
        "shows": "A child running"
      },
      "teaches": []
    },
    {
      "slide": 2,
      "does": "Introduce the approved objectives",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": []
    },
    {
      "slide": 3,
      "does": "Teach the three parts and correct the heart-making-blood misconception",
      "look_at": {
        "kind": "diagram",
        "shows": "The heart connected to blood vessels carrying blood"
      },
      "teaches": [1]
    },
    {
      "slide": 4,
      "does": "Work through the blood's complete journey",
      "look_at": {
        "kind": "diagram",
        "shows": "A linked route through heart, lungs, heart and body"
      },
      "teaches": [2]
    },
    {
      "slide": 5,
      "does": "Practise describing the same journey",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [1, 2]
    },
    {
      "slide": 6,
      "does": "Check understanding of the route with a hinge question",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [2]
    },
    {
      "slide": 7,
      "does": "Explain the link between exercise, oxygen and heart rate",
      "look_at": {
        "kind": "diagram",
        "shows": "Working muscles needing more oxygen and the heart pumping faster"
      },
      "teaches": [3]
    },
    {
      "slide": 8,
      "does": "Model reading and comparing pulse measurements",
      "look_at": {
        "kind": "diagram",
        "shows": "Resting and post-exercise pulse measurements"
      },
      "teaches": [3]
    },
    {
      "slide": 9,
      "does": "Practise comparing a similar pair of measurements",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [3]
    },
    {
      "slide": 10,
      "does": "Measure pulse and apply the explanation to new evidence",
      "look_at": {
        "kind": "picture",
        "shows": "Two fingertips finding a pulse at the wrist"
      },
      "teaches": [3]
    }
  ],
  "title": {
    "template": "title",
    "heading": "The heart and circulation",
    "lead": "Recall: what changes in your body when you run?",
    "picture": {
      "shows": "a primary-aged child running across a school playground",
      "must_see": [
        "running child",
        "bent arms",
        "school playground"
      ],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "visual-text",
      "heading": "Does the heart make blood?",
      "lead": "No. The heart is a muscle that pumps blood already in the body.",
      "points": [
        {
          "label": "Heart",
          "text": "Pumps blood around the system."
        },
        {
          "label": "Blood",
          "text": "Carries oxygen and nutrients."
        },
        {
          "label": "Blood vessels",
          "text": "Tubes that transport blood."
        }
      ],
      "figure": {
        "kind": "labelled-diagram",
        "shows": "A simple human outline with the heart in the chest, connected branching blood vessels reaching the arms, trunk and legs, and a magnified vessel containing blood. Use leader lines to identify the three parts; avoid suggesting blood sits freely inside the body.",
        "labels": [
          "Heart",
          "Blood vessels",
          "Blood"
        ]
      }
    },
    {
      "template": "big-visual",
      "heading": "Follow one complete journey",
      "lead": "Blood returns to the heart between its lung and body journeys.",
      "figure": {
        "kind": "flow",
        "shows": "A worked example following blood from the heart to the lungs, back to the heart, out to the body and back again. Two heart boxes represent different sides of the same heart.",
        "alt": "Blood travels from the heart to the lungs, back to the heart, to the body and back to the heart.",
        "title": null,
        "nodes": [
          "Heart: pumps to lungs",
          "Lungs: oxygen enters blood",
          "Heart: pumps to body",
          "Body: uses oxygen + nutrients"
        ],
        "links": [
          {
            "from": 0,
            "to": 1,
            "label": "blood vessels"
          },
          {
            "from": 1,
            "to": 2,
            "label": "blood vessels"
          },
          {
            "from": 2,
            "to": 3,
            "label": "blood vessels"
          },
          {
            "from": 3,
            "to": 0,
            "label": "blood vessels"
          }
        ]
      }
    },
    {
      "template": "practice",
      "heading": "Trace the journey yourself",
      "questions": [
        "Start at the heart. Write the route through the lungs and body, ending at the heart.",
        "Describe what happens to blood at the lungs and what it delivers to the body.",
        "Name the tubes blood travels through. What makes the blood move?"
      ],
      "instruction": "Write your answers on the worksheet.",
      "picture": null
    },
    {
      "template": "hinge",
      "heading": "Check the route",
      "stem": "Where does blood go immediately after leaving the lungs?",
      "options": [
        "Straight to the leg muscles",
        "Back to the heart",
        "Out of the body",
        "Back into the lungs"
      ],
      "correct": 2
    },
    {
      "template": "visual-text",
      "heading": "Why does exercise change your heartbeat?",
      "lead": "Working muscles need more oxygen. A faster heartbeat helps deliver it.",
      "points": [
        "The lungs transfer oxygen into blood.",
        "The heart pumps blood faster to muscles.",
        "Your pulse lets you count heartbeats."
      ],
      "figure": {
        "kind": "flow",
        "shows": "The causal link between exercise, greater muscle oxygen demand and faster delivery of oxygen in blood.",
        "alt": "During exercise, working muscles need more oxygen, so the heart beats faster and more oxygen reaches the muscles each minute.",
        "title": null,
        "nodes": [
          "Muscles work harder",
          "Muscles need more oxygen",
          "Heart beats faster"
        ],
        "links": [
          {
            "from": 0,
            "to": 1,
            "label": null
          },
          {
            "from": 1,
            "to": 2,
            "label": null
          }
        ]
      }
    },
    {
      "template": "visual-text",
      "heading": "Worked example: Sam's pulse",
      "lead": "Sam counted for a full minute each time.",
      "points": [
        "Increase: 112 − 76 = 36 beats per minute.",
        "His working muscles needed more oxygen.",
        "His faster heartbeat helped deliver it."
      ],
      "figure": {
        "kind": "table",
        "shows": "Sam's pulse at rest and immediately after one minute of marching.",
        "alt": "Sam's pulse was 76 beats per minute at rest and 112 beats per minute after marching.",
        "title": null,
        "header": [
          "When",
          "Beats per minute"
        ],
        "rows": [
          [
            "Rest",
            "76"
          ],
          [
            "Marching",
            "112"
          ]
        ]
      }
    },
    {
      "template": "practice",
      "heading": "Your turn: Aisha's pulse",
      "questions": [
        "Aisha's pulse was 80 beats per minute at rest and 120 after marching. Calculate the increase.",
        "Explain why her pulse changed. Use muscles, oxygen, blood and heart.",
        "Stretch: Ben's pulse stayed at 80 after marching. Does one result prove exercise never raises pulse? Explain."
      ],
      "instruction": "Write your working and explanations.",
      "picture": null
    },
    {
      "template": "steps",
      "heading": "Investigate your own pulse",
      "points": [
        "Rest seated. Find your wrist pulse.",
        "Count beats for 60 seconds. Record.",
        "March for 60 seconds; count again for 60.",
        "Compare results. Explain the change."
      ],
      "figure": {
        "shows": "a close-up of a child's index and middle fingertips resting gently on the thumb side of the opposite inner wrist to find a pulse",
        "must_see": [
          "two fingertips",
          "inner wrist",
          "palm facing up"
        ],
        "subject": "generic"
      }
    }
  ]
}
